public static void main(String[] args)
{
    FastReader sc = new FastReader();
    PrintWriter out = new PrintWriter(System.out);
    int n = sc.nextInt();
    int[] arr = new int[2 * n];
    for (int i = 0; i < 2 * n; ++i) arr[i] = sc.nextInt();
    int c = 0;
    for (int color = 1; color <= n; ++color) {
        int firstIndex = -1;
        int secondIndex = -1;
        for (int i = 0; i < 2 * n; ++i) {
            if (arr[i] == color) {
                if (firstIndex == -1) {
                    firstIndex = i;
                } else {
                    secondIndex = i;
                    break;
                }
            }
        }
        if (secondIndex - firstIndex == 2) {
            ++c;
        }
    }
    out.println(c);
    out.flush();
}
